import React, { useEffect, useMemo, useRef, useState } from 'react';
import { io } from 'socket.io-client';
import { useNavigate } from 'react-router-dom';
import { api, normalizeArrayPayload, normalizeTrades, badgeClass } from '../services/api';

const SOCKET_URL = 'http://localhost:5000';

function RiskTrendChart({ logs }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const width = canvas.offsetWidth || 420;
    canvas.width = width * 2;
    canvas.height = 180 * 2;
    canvas.style.height = '180px';

    const ctx = canvas.getContext('2d');
    ctx.scale(2, 2);
    ctx.clearRect(0, 0, width, 180);

    const data = [...logs]
      .slice(0, 20)
      .reverse()
      .map((l, i) => ({
        x: i,
        y: Number(l.risk_score || 0),
      }));

    if (!data.length) {
      ctx.fillStyle = '#55604f';
      ctx.font = '13px Inter';
      ctx.fillText('No live risk points yet', 16, 92);
      return;
    }

    const pad = 18;
    const chartW = width - pad * 2;
    const chartH = 130;
    const maxY = Math.max(100, ...data.map((d) => d.y));

    for (let i = 0; i < 4; i += 1) {
      const y = pad + (chartH / 3) * i;
      ctx.strokeStyle = 'rgba(255,255,255,0.05)';
      ctx.beginPath();
      ctx.moveTo(pad, y);
      ctx.lineTo(width - pad, y);
      ctx.stroke();
    }

    const points = data.map((d, idx) => ({
      x: pad + (idx / Math.max(data.length - 1, 1)) * chartW,
      y: pad + chartH - (d.y / maxY) * chartH,
      raw: d.y,
    }));

    ctx.beginPath();
    points.forEach((p, i) => {
      if (i === 0) ctx.moveTo(p.x, p.y);
      else ctx.lineTo(p.x, p.y);
    });
    ctx.strokeStyle = '#b8ff4f';
    ctx.lineWidth = 3;
    ctx.shadowColor = 'rgba(184,255,79,0.35)';
    ctx.shadowBlur = 18;
    ctx.stroke();
    ctx.shadowBlur = 0;

    ctx.lineTo(points[points.length - 1].x, pad + chartH);
    ctx.lineTo(points[0].x, pad + chartH);
    ctx.closePath();
    const grad = ctx.createLinearGradient(0, pad, 0, pad + chartH);
    grad.addColorStop(0, 'rgba(184,255,79,0.22)');
    grad.addColorStop(1, 'rgba(184,255,79,0.02)');
    ctx.fillStyle = grad;
    ctx.fill();

    points.forEach((p) => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, 3.4, 0, Math.PI * 2);
      ctx.fillStyle = p.raw >= 70 ? '#ff5555' : p.raw >= 40 ? '#ffb020' : '#b8ff4f';
      ctx.fill();
    });
  }, [logs]);

  return <canvas ref={canvasRef} style={{ width: '100%', display: 'block' }} />;
}

function StatCard({ label, value, sub, color, pulse }) {
  return (
    <div className={`glass-strong card-hover ${pulse ? 'fraud-pulse' : ''}`} style={{ padding: 22 }}>
      <div style={{ color: '#808779', fontSize: 12, fontWeight: 800, letterSpacing: '0.08em', textTransform: 'uppercase', marginBottom: 14 }}>
        {label}
      </div>
      <div style={{ fontSize: 42, fontWeight: 900, color, marginBottom: 8, textShadow: `0 0 18px ${color}33` }}>
        {value}
      </div>
      <div style={{ color: '#5e6558', fontSize: 13 }}>{sub}</div>
    </div>
  );
}

export default function DashboardPage() {
  const navigate = useNavigate();
  const [stats, setStats] = useState({});
  const [trades, setTrades] = useState([]);
  const [riskLogs, setRiskLogs] = useState([]);
  const [cycles, setCycles] = useState([]);
  const [liveAlerts, setLiveAlerts] = useState([]);
  const [loading, setLoading] = useState(true);

  const loadAll = async () => {
    try {
      const [statsRes, tradesRes, riskRes, cycleRes] = await Promise.all([
        api.fetchStats(),
        api.fetchTrades(1, 50),
        api.fetchRiskLogs(),
        api.fetchFraudCycles(),
      ]);

      const logs = normalizeArrayPayload(riskRes);
      const baseTrades = normalizeArrayPayload(tradesRes);
      const mergedTrades = normalizeTrades(baseTrades, logs);

      setStats(statsRes || {});
      setRiskLogs(logs);
      setTrades(mergedTrades);
      setCycles(normalizeArrayPayload(cycleRes));
      setLoading(false);
    } catch (err) {
      console.error(err);
      setLoading(false);
    }
  };

  useEffect(() => {
    loadAll();
    const id = setInterval(loadAll, 2000);

    const socket = io(SOCKET_URL, { transports: ['websocket', 'polling'] });
    const refresh = async (payload) => {
      const item = Array.isArray(payload) ? payload[0] : payload;
      setLiveAlerts((prev) => [item, ...prev].slice(0, 8));
      await loadAll();
    };

    socket.on('fraud_alert', refresh);
    socket.on('fraud_detected', refresh);
    socket.on('risk_log', refresh);
    socket.on('trade_inserted', loadAll);

    return () => {
      clearInterval(id);
      socket.disconnect();
    };
  }, []);

  const computed = useMemo(() => {
    const totalTrades = Number(stats.total_trades ?? trades.length ?? 0);
    const fraudRings = Number(stats.fraud_rings_detected ?? cycles.length ?? 0);
    const highRisk = Number(
      stats.high_risk_traders ??
      riskLogs.filter((l) => Number(l.risk_score || 0) >= 70).length ??
      0
    );
    const monitored = Number(stats.total_traders ?? stats.monitored_traders ?? 0);
    return { totalTrades, fraudRings, highRisk, monitored };
  }, [stats, trades, cycles, riskLogs]);

  return (
    <div className="page-wrap grid-bg">
      <div className="page-container">
        <div style={{ display: 'flex', justifyContent: 'space-between', gap: 20, alignItems: 'flex-start', marginBottom: 28 }}>
          <div>
            <h1 style={{ fontSize: 28, fontWeight: 900, margin: 0, letterSpacing: '-0.03em' }}>
              TraceNet <span className="neon-strong">Dashboard</span>
            </h1>
            <div style={{ marginTop: 10, display: 'flex', alignItems: 'center', gap: 10, color: '#899182' }}>
              <span className="live-dot blink" />
              <span>Live monitoring active</span>
            </div>
          </div>

          <div style={{ display: 'flex', gap: 10 }}>
            <button className="btn-outline" onClick={() => navigate('/fraud')}>Fraud Engine</button>
            <button className="btn-outline" onClick={() => navigate('/traders')}>Traders</button>
          </div>
        </div>

        <div className="kpi-grid" style={{ marginBottom: 18 }}>
          <StatCard label="Total Trades" value={computed.totalTrades} sub="Live count" color="#b8ff4f" />
          <StatCard label="Fraud Rings" value={computed.fraudRings} sub="Detected circular loops" color="#ff5555" pulse={computed.fraudRings > 0} />
          <StatCard label="High Risk Transactions" value={riskLogs.filter((r) => Number(r.risk_score || 0) >= 70).length} sub="Risk score ≥ 70" color="#ffb020" />
          <StatCard label="Monitored Traders" value={computed.monitored} sub="Registry size" color="#b8ff4f" />
        </div>

        {!!liveAlerts.length && (
          <div className="glass-strong fraud-pulse" style={{ padding: 16, marginBottom: 18 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
              <span className="live-dot-red blink" />
              <div style={{ color: '#ff8f8f', fontWeight: 800 }}>Live Alert</div>
              <div style={{ color: '#cab0b0', fontSize: 13 }}>
                {liveAlerts[0]?.reason || 'Circular trading activity detected'}
              </div>
            </div>
          </div>
        )}

        <div className="grid-2" style={{ marginBottom: 20 }}>
          <div className="glass-strong" style={{ overflow: 'hidden' }}>
            <div style={{ padding: '20px 20px 14px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div style={{ fontSize: 16, fontWeight: 900 }}>Recent Trades</div>
              <button className="btn-ghost" onClick={() => navigate('/transactions')}>View all →</button>
            </div>

            <div className="scroll-y" style={{ maxHeight: 380 }}>
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Trade ID</th>
                    <th>Stock</th>
                    <th>Seller</th>
                    <th>Buyer</th>
                    <th>Price</th>
                    <th>Qty</th>
                    <th>Risk</th>
                  </tr>
                </thead>
                <tbody>
                  {trades.slice(0, 16).map((t) => (
                    <tr key={t.trade_id}>
                      <td style={{ color: '#81867b', fontFamily: 'monospace' }}>#{t.trade_id}</td>
                      <td><span className="neon" style={{ fontWeight: 800 }}>{t.symbol || t.stock_symbol || `#${t.stock_id}`}</span></td>
                      <td>{t.seller_name || `T${t.seller_id}`}</td>
                      <td>{t.buyer_name || `T${t.buyer_id}`}</td>
                      <td>${Number(t.price || 0).toFixed(2)}</td>
                      <td>{Number(t.quantity || 0)}</td>
                      <td>
                        <span className={badgeClass(t.risk_score)}>{t.risk_score || 0}</span>
                      </td>
                    </tr>
                  ))}
                  {!trades.length && (
                    <tr>
                      <td colSpan="7">
                        <div className="empty-state">No trades yet. Start the live feed to populate transactions.</div>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>

          <div style={{ display: 'grid', gap: 18 }}>
            <div className="glass-strong" style={{ padding: 20 }}>
              <div style={{ fontSize: 16, fontWeight: 900, marginBottom: 12 }}>Risk Trend</div>
              <RiskTrendChart logs={riskLogs} />
              <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 8, color: '#76806e', fontSize: 12 }}>
                <span>Last 20 events</span>
                <span className="neon" style={{ fontWeight: 800 }}>LIVE</span>
              </div>
            </div>

            <div className="glass-strong" style={{ overflow: 'hidden' }}>
              <div style={{ padding: '18px 20px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div style={{ fontSize: 16, fontWeight: 900 }}>Fraud Alerts</div>
                <span className="badge badge-high">{riskLogs.length}</span>
              </div>

              <div className="scroll-y" style={{ maxHeight: 210 }}>
                {riskLogs.slice(0, 8).map((log, idx) => (
                  <div
                    key={`${log.trade_id}-${idx}`}
                    style={{
                      padding: '12px 20px',
                      borderTop: '1px solid rgba(255,255,255,0.04)',
                      display: 'flex',
                      justifyContent: 'space-between',
                      gap: 14,
                    }}
                  >
                    <div>
                      <div style={{ color: '#ff7f7f', fontSize: 13, fontWeight: 800 }}>
                        Trade #{log.trade_id}
                      </div>
                      <div style={{ color: '#858d7f', fontSize: 12, marginTop: 4 }}>
                        {log.reason || 'Suspicious circular trade pattern'}
                      </div>
                    </div>
                    <span className={badgeClass(log.risk_score)}>{log.risk_score}</span>
                  </div>
                ))}
                {!riskLogs.length && <div className="empty-state">No risk logs yet.</div>}
              </div>
            </div>
          </div>
        </div>

        <div className="grid-3">
          <div className="glass-strong card-hover" style={{ padding: 24, cursor: 'pointer' }} onClick={() => navigate('/fraud')}>
            <div style={{ fontWeight: 900, fontSize: 16 }}>🔁 Fraud Cycles</div>
            <div style={{ color: '#7f8779', marginTop: 6, fontSize: 14 }}>Detected circular trading rings</div>
            <div className="neon" style={{ marginTop: 14, fontWeight: 800 }}>Open →</div>
          </div>

          <div className="glass-strong card-hover" style={{ padding: 24, cursor: 'pointer' }} onClick={() => navigate('/traders')}>
            <div style={{ fontWeight: 900, fontSize: 16 }}>👤 Traders</div>
            <div style={{ color: '#7f8779', marginTop: 6, fontSize: 14 }}>Trust scores, search, history and profile</div>
            <div className="neon" style={{ marginTop: 14, fontWeight: 800 }}>Open →</div>
          </div>

          <div className="glass-strong card-hover" style={{ padding: 24, cursor: 'pointer' }} onClick={() => navigate('/transactions')}>
            <div style={{ fontWeight: 900, fontSize: 16 }}>📋 All Transactions</div>
            <div style={{ color: '#7f8779', marginTop: 6, fontSize: 14 }}>Live transaction risk analysis table</div>
            <div className="neon" style={{ marginTop: 14, fontWeight: 800 }}>Open →</div>
          </div>
        </div>

        {loading && <div style={{ color: '#7b8474', marginTop: 18 }}>Loading live dashboard...</div>}
      </div>
    </div>
  );
}
